source('mp10_immune_endothelial_mechanisms_v1/scripts/common.R');suppressPackageStartupMessages(library(Seurat));args<-commandArgs(TRUE);lin<-args[1];a<-rd(paste0('scenic_membership_',lin,'.tsv.gz'));genes<-rd(paste0('scenic_genes_',lin,'.tsv'))$gene
stopifnot(file.exists(file.path(B,'objects/scenic',paste0(lin,'_regulons.pkl'))));o<-qread(objpath,nthreads=1);x<-LayerData(o,assay='RNA',layer='data');
