cc<-LayerData(o,assay='RNA',layer='counts');stopifnot(identical(dimnames(cc),dimnames(x)));set.seed(123);audit_ids<-sample(a$barcode,min(100L,nrow(a)));csub<-cc[,audit_ids,drop=FALSE];lib<-Matrix::colSums(csub);expected<-log1p(t(t(csub)/lib)*10000);delta<-x[,audit_ids,drop=FALSE]-expected;max_error<-if(length(delta@x))max(abs(delta@x))else 0;srcmeta<-o[[]][audit_ids,,drop=FALSE];audit<-data.table(lineage=lin,barcode=audit_ids,total_counts=lib,nCount_metadata=srcmeta$nCount_RNA,raw_nonnegative_integer=TRUE,normalization_max_abs_error=max_error,normalization='log1p(UMI / full RNA library * 10000)');stopifnot(all(csub@x>=0&csub@x==round(csub@x)),all(lib==srcmeta$nCount_RNA),max_error<1e-7);put(audit,paste0('source_normalization_audit_',lin,'.tsv'));rm(cc,csub,expected,delta)
dir.create(file.path(B,'objects/scenic/aucell_parts'),showWarnings=FALSE);tmp<-file.path(B,'objects/scenic',paste0(lin,'_temporary_expression.tsv.gz'));parts<-split(seq_len(nrow(a)),ceiling(seq_len(nrow(a))/3000));outputs<-character()
for(i in seq_along(parts)){
 ids<-a$barcode[parts[[i]]];of<-file.path(B,'objects/scenic/aucell_parts',sprintf('%s_%03d.tsv.gz',lin,i));sig<-digest(list(ids,genes,digest(file.path(B,'objects/scenic',paste0(lin,'_regulons.pkl')),file=TRUE,algo='sha256'),123,.05,'barcode_order_v2',if(lin=='Epi')'Full_and_M20_masked'else'Full'),algo='sha256');outputs<-c(outputs,of)
 if(file.exists(of)&&(lin!='Epi'||file.exists(sub('.tsv.gz$','_M20-masked.tsv.gz',of)))&&file.exists(paste0(of,'.sha256'))&&readLines(paste0(of,'.sha256'))==sig)next
 fwrite(data.table(gene=genes,as.data.table(as.matrix(x[genes,ids,drop=FALSE]))),tmp,sep='\t',compress='gzip')
